// Package arisan implements a rotating savings circle (arisan) on Gno.land.
//
// Arisan is an Indonesian tradition: a group of people each contribute a
// fixed amount every round, and each round one member — in rotation order —
// takes the whole pot. All rules and all money live on-chain in this realm.
//
// Rules:
//   - Anyone can create a circle (name, contribution per round in ugnot,
//     maximum members). The creator is the organizer.
//   - Members join while the circle is open (before round 1 starts).
//     Join order IS the rotation order: deterministic, no randomness.
//   - Every round, each member deposits exactly the contribution via the
//     -send envelope. A member who has not paid yet is shown as BELUM BAYAR.
//   - The organizer advances the round only when every member has paid.
//     On advance, the pot (members x contribution) is paid from the realm
//     to the member whose turn it is, then the next round begins.
//   - All money accounting is exact int64 ugnot. No fees are taken.
package arisan

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Circle is one arisan group.
type Circle struct {
	ID           int
	Name         string
	Organizer    address
	Contribution int64 // ugnot per member per round
	MaxMembers   int
	Members      []address // join order == rotation order
	Round        int       // current round; 0 = not started
	Started      bool
	Paid         []bool // current-round payment status, aligned with Members
	PaidCount    []int  // total rounds each member has paid
	TurnsTaken   []int  // rounds each member has taken the pot
	Pot          int64  // ugnot currently held for this circle
	TotalPaidOut int64  // total ugnot paid out to turn-takers so far
}

var (
	circles avl.Tree // circle ID (string) -> *Circle
	nextID  int
)

// require panics with msg unless check holds. A panic aborts the whole
// transaction: no state change, no funds move.
func require(check bool, msg string) {
	if !check {
		panic(msg)
	}
}

// mustGetCircle returns the circle with the given ID or panics.
func mustGetCircle(id int) *Circle {
	c := circles.Get(strconv.Itoa(id))
	if c == nil {
		panic("unknown circle ID")
	}
	return c.(*Circle)
}

// memberIndex returns the index of addr in c.Members, or -1.
func memberIndex(c *Circle, a address) int {
	for i, m := range c.Members {
		if m == a {
			return i
		}
	}
	return -1
}

// turnTaker is the member whose turn it is in the current round.
// Round 1 -> Members[0], round 2 -> Members[1], and so on, wrapping around.
func turnTaker(c *Circle) address {
	return c.Members[(c.Round-1)%len(c.Members)]
}

// turnTakerIndex is the index of the current turn-taker in c.Members.
func turnTakerIndex(c *Circle) int {
	return (c.Round - 1) % len(c.Members)
}

// allPaid reports whether every member has paid for the current round.
func allPaid(c *Circle) bool {
	for _, p := range c.Paid {
		if !p {
			return false
		}
	}
	return true
}

// caller returns the address that called this realm function. Only direct
// user calls (maketx call) are accepted: an intermediate realm must not be
// able to act on a user's behalf.
func caller(cur realm) address {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	return cur.Previous().Address()
}

// CreateCircle creates a new arisan circle and returns its ID.
// The caller becomes the organizer.
func CreateCircle(cur realm, name string, contribution int64, maxMembers int) int {
	caller(cur)
	require(name != "", "circle name must not be empty")
	require(contribution > 0, "contribution must be positive (ugnot)")
	require(maxMembers >= 2, "a circle needs at least 2 members")
	nextID++
	c := &Circle{
		ID:           nextID,
		Name:         name,
		Organizer:    cur.Previous().Address(),
		Contribution: contribution,
		MaxMembers:   maxMembers,
		Members:      []address{},
		Round:        0,
		Started:      false,
		Paid:         []bool{},
		PaidCount:    []int{},
		TurnsTaken:   []int{},
		Pot:          0,
		TotalPaidOut: 0,
	}
	circles.Set(strconv.Itoa(c.ID), c)
	return c.ID
}

// JoinCircle adds the caller to a circle. The circle must still be open
// (round 1 has not started) and not full. Join order is rotation order.
func JoinCircle(cur realm, id int) {
	who := caller(cur)
	c := mustGetCircle(id)
	require(!c.Started, "circle already started; joining is closed")
	require(memberIndex(c, who) < 0, "already a member of this circle")
	require(len(c.Members) < c.MaxMembers, "circle is full")
	c.Members = append(c.Members, who)
	c.Paid = append(c.Paid, false)
	c.PaidCount = append(c.PaidCount, 0)
	c.TurnsTaken = append(c.TurnsTaken, 0)
	circles.Set(strconv.Itoa(id), c)
}

// StartCircle starts round 1. Only the organizer can start, and only with
// at least 2 members.
func StartCircle(cur realm, id int) {
	who := caller(cur)
	c := mustGetCircle(id)
	require(who == c.Organizer, "only the organizer can start the circle")
	require(!c.Started, "circle already started")
	require(len(c.Members) >= 2, "need at least 2 members to start")
	c.Started = true
	c.Round = 1
	circles.Set(strconv.Itoa(id), c)
}

// Deposit pays the caller's contribution for the current round.
// The call must carry exactly the contribution in ugnot via -send.
// Anything else (wrong amount, wrong denom, extra coins) aborts.
func Deposit(cur realm, id int) {
	who := caller(cur)
	c := mustGetCircle(id)
	require(c.Started, "circle has not started yet")
	i := memberIndex(c, who)
	require(i >= 0, "only members can deposit")
	require(!c.Paid[i], "already paid for this round")
	sent := unsafe.OriginSend()
	require(len(sent) == 1, "send exactly the contribution (one coin)")
	require(sent[0].Denom == "ugnot", "contribution must be paid in ugnot")
	require(sent[0].Amount == c.Contribution, "send exactly the contribution amount")
	c.Paid[i] = true
	c.PaidCount[i]++
	c.Pot += c.Contribution
	circles.Set(strconv.Itoa(id), c)
}

// AdvanceRound closes the current round and pays the pot to the member
// whose turn it is. Only the organizer can advance, and only when every
// member has paid for the round. The next round then begins.
func AdvanceRound(cur realm, id int) {
	who := caller(cur)
	c := mustGetCircle(id)
	require(who == c.Organizer, "only the organizer can advance the round")
	require(c.Started, "circle has not started yet")
	require(allPaid(c), "not all members have paid for this round")
	takerIdx := turnTakerIndex(c)
	taker := c.Members[takerIdx]
	expectedPot := int64(len(c.Members)) * c.Contribution
	require(c.Pot == expectedPot, "pot accounting mismatch; refusing to pay out")
	realmAddr := cur.Address()
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	require(b.GetCoin(realmAddr, "ugnot") >= expectedPot, "realm balance below pot; refusing to pay out")
	b.SendCoins(realmAddr, taker, chain.NewCoins(chain.NewCoin("ugnot", expectedPot)))
	c.TurnsTaken[takerIdx]++
	c.TotalPaidOut += expectedPot
	c.Pot = 0
	c.Round++
	for i := range c.Paid {
		c.Paid[i] = false
	}
	circles.Set(strconv.Itoa(id), c)
}

// CircleCount returns how many circles exist.
func CircleCount() int {
	return nextID
}

// CircleInfo returns a one-line summary of a circle.
func CircleInfo(id int) string {
	c := mustGetCircle(id)
	status := "open"
	if c.Started {
		status = "round " + strconv.Itoa(c.Round)
	}
	return ufmt.Sprintf("#%d %s | %s | %d ugnot/round | %d/%d members | pot %d ugnot | paid out %d ugnot",
		c.ID, c.Name, status, c.Contribution, len(c.Members), c.MaxMembers, c.Pot, c.TotalPaidOut)
}

// memberLine renders one member row for Render.
func memberLine(c *Circle, i int) string {
	m := c.Members[i]
	paid := "BELUM BAYAR"
	if c.Started && c.Paid[i] {
		paid = "SUDAH BAYAR"
	} else if !c.Started {
		paid = "menunggu mulai"
	}
	turn := ""
	if c.Started && i == turnTakerIndex(c) {
		turn = " <-- GILIRAN ROUND INI"
	}
	return ufmt.Sprintf("- %s | %s | bayar %d round | ambil pot %d kali%s",
		m.String(), paid, c.PaidCount[i], c.TurnsTaken[i], turn)
}

// renderCircle renders the detail view of one circle.
func renderCircle(c *Circle) string {
	out := ufmt.Sprintf("# Arisan #%d: %s\n\n", c.ID, c.Name)
	out += ufmt.Sprintf("- Penyelenggara (organizer): %s\n", c.Organizer.String())
	out += ufmt.Sprintf("- Iuran per round: %d ugnot\n", c.Contribution)
	out += ufmt.Sprintf("- Anggota: %d / %d\n", len(c.Members), c.MaxMembers)
	if !c.Started {
		out += "- Status: BELUM MULAI (menunggu anggota, organizer memanggil StartCircle)\n"
	} else {
		out += ufmt.Sprintf("- Status: ROUND %d\n", c.Round)
		out += ufmt.Sprintf("- Giliran round ini: %s\n", turnTaker(c).String())
		out += ufmt.Sprintf("- Pot round ini: %d ugnot\n", c.Pot)
	}
	out += ufmt.Sprintf("- Total sudah dibayarkan ke pemenang giliran: %d ugnot\n\n", c.TotalPaidOut)
	out += "## Anggota (urutan gabung = urutan giliran)\n\n"
	for i := range c.Members {
		out += memberLine(c, i) + "\n"
	}
	return out
}

// Render shows the dashboard: all circles, or one circle's detail when the
// path is a circle ID (e.g. /1).
func Render(path string) string {
	if len(path) > 0 && path[0] == '/' {
		path = path[1:]
	}
	if id, err := strconv.Atoi(path); err == nil {
		if c := circles.Get(strconv.Itoa(id)); c != nil {
			return renderCircle(c.(*Circle))
		}
		return "404: circle tidak ditemukan"
	}
	if nextID == 0 {
		return "# Arisan — Rotating Savings Circle\n\nBelum ada circle. Buat circle pertama dengan CreateCircle.\n"
	}
	out := "# Arisan — Rotating Savings Circle\n\n"
	out += "Setiap anggota iuran tiap round; tiap round satu anggota (sesuai urutan gabung) mengambil seluruh pot.\n\n"
	out += "## Circles\n\n"
	for id := 1; id <= nextID; id++ {
		if c := circles.Get(strconv.Itoa(id)); c != nil {
			out += "- " + CircleInfo(id) + "\n"
		}
	}
	return out
}

package arisan

import (
	"chain"
	"chain/banker"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const testRealmPath = "gno.land/r/g1u9frcg00ncx6ws8h6whtkdg2z4gsv0hjvzh20w/arisan"

func resetTestState() {
	circles = avl.Tree{}
	nextID = 0
}

func testAddrs() (organizer, m1, m2, m3 address) {
	return testutils.TestAddress("organizer"),
		testutils.TestAddress("member1"),
		testutils.TestAddress("member2"),
		testutils.TestAddress("member3")
}

// setupCircle creates a circle with 3 members and starts round 1.
// Contribution is 1000 ugnot, max 4 members.
func setupCircle(cur realm, t *testing.T) (int, address, address, address, address) {
	org, m1, m2, m3 := testAddrs()
	testing.SetRealm(testing.NewUserRealm(org))
	id := CreateCircle(cross(cur), "Arisan RT 05", 1000, 4)
	uassert.Equal(t, 1, id)
	testing.SetRealm(testing.NewUserRealm(m1))
	JoinCircle(cross(cur), id)
	testing.SetRealm(testing.NewUserRealm(m2))
	JoinCircle(cross(cur), id)
	testing.SetRealm(testing.NewUserRealm(m3))
	JoinCircle(cross(cur), id)
	testing.SetRealm(testing.NewUserRealm(org))
	StartCircle(cross(cur), id)
	return id, org, m1, m2, m3
}

func depositAs(cur realm, who address, id int, amount int64) {
	testing.SetRealm(testing.NewUserRealm(who))
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: amount}})
	Deposit(cross(cur), id)
}

func TestCreateCircle(cur realm, t *testing.T) {
	defer resetTestState()
	org, _, _, _ := testAddrs()
	testing.SetRealm(testing.NewUserRealm(org))
	id := CreateCircle(cross(cur), "Arisan RT 05", 1000, 4)
	uassert.Equal(t, 1, id)
	c := mustGetCircle(id)
	uassert.Equal(t, "Arisan RT 05", c.Name)
	uassert.Equal(t, org, c.Organizer)
	uassert.Equal(t, int64(1000), c.Contribution)
	uassert.Equal(t, 4, c.MaxMembers)
	uassert.False(t, c.Started)
	uassert.Equal(t, 0, c.Round)
	uassert.Equal(t, 1, CircleCount())

	// Invalid creates abort.
	uassert.AbortsWithMessage(t, cur, "circle name must not be empty", func() {
		CreateCircle(cross(cur), "", 1000, 4)
	})
	uassert.AbortsWithMessage(t, cur, "contribution must be positive (ugnot)", func() {
		CreateCircle(cross(cur), "X", 0, 4)
	})
	uassert.AbortsWithMessage(t, cur, "a circle needs at least 2 members", func() {
		CreateCircle(cross(cur), "X", 1000, 1)
	})
}

func TestJoinAndStart(cur realm, t *testing.T) {
	defer resetTestState()
	org, m1, m2, m3 := testAddrs()
	testing.SetRealm(testing.NewUserRealm(org))
	id := CreateCircle(cross(cur), "Arisan RT 05", 1000, 4)

	// Only the organizer can start.
	testing.SetRealm(testing.NewUserRealm(m1))
	uassert.AbortsWithMessage(t, cur, "only the organizer can start the circle", func() {
		StartCircle(cross(cur), id)
	})
	// Cannot start with fewer than 2 members.
	testing.SetRealm(testing.NewUserRealm(org))
	uassert.AbortsWithMessage(t, cur, "need at least 2 members to start", func() {
		StartCircle(cross(cur), id)
	})

	testing.SetRealm(testing.NewUserRealm(m1))
	JoinCircle(cross(cur), id)
	// Duplicate join aborts.
	uassert.AbortsWithMessage(t, cur, "already a member of this circle", func() {
		JoinCircle(cross(cur), id)
	})
	testing.SetRealm(testing.NewUserRealm(m2))
	JoinCircle(cross(cur), id)
	testing.SetRealm(testing.NewUserRealm(m3))
	JoinCircle(cross(cur), id)

	c := mustGetCircle(id)
	uassert.Equal(t, 3, len(c.Members))
	// Join order is rotation order.
	uassert.Equal(t, m1, c.Members[0])
	uassert.Equal(t, m2, c.Members[1])
	uassert.Equal(t, m3, c.Members[2])

	testing.SetRealm(testing.NewUserRealm(org))
	StartCircle(cross(cur), id)
	c = mustGetCircle(id)
	uassert.True(t, c.Started)
	uassert.Equal(t, 1, c.Round)

	// Joining after start aborts.
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("latecomer")))
	uassert.AbortsWithMessage(t, cur, "circle already started; joining is closed", func() {
		JoinCircle(cross(cur), id)
	})
}

func TestDepositRules(cur realm, t *testing.T) {
	defer resetTestState()
	id, org, m1, m2, m3 := setupCircle(cur, t)
	_ = org
	_ = m2
	_ = m3

	// Non-member cannot deposit.
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("outsider")))
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 1000}})
	uassert.AbortsWithMessage(t, cur, "only members can deposit", func() {
		Deposit(cross(cur), id)
	})

	// Wrong amount aborts.
	testing.SetRealm(testing.NewUserRealm(m1))
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 999}})
	uassert.AbortsWithMessage(t, cur, "send exactly the contribution amount", func() {
		Deposit(cross(cur), id)
	})
	// Wrong denom aborts.
	testing.SetOriginSend(chain.Coins{{Denom: "atom", Amount: 1000}})
	uassert.AbortsWithMessage(t, cur, "contribution must be paid in ugnot", func() {
		Deposit(cross(cur), id)
	})

	// Correct deposit works.
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 1000}})
	Deposit(cross(cur), id)
	c := mustGetCircle(id)
	uassert.True(t, c.Paid[0])
	uassert.Equal(t, int64(1000), c.Pot)
	uassert.Equal(t, 1, c.PaidCount[0])

	// Double deposit in the same round aborts.
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 1000}})
	uassert.AbortsWithMessage(t, cur, "already paid for this round", func() {
		Deposit(cross(cur), id)
	})
}

func TestAdvanceFullRound(cur realm, t *testing.T) {
	defer resetTestState()
	// Fund the realm so payouts have a balance to draw from in the test VM.
	pkgAddr := chain.PackageAddress(testRealmPath)
	testing.IssueCoins(pkgAddr, chain.Coins{{Denom: "ugnot", Amount: 100000000}})
	rb := banker.NewReadonlyBanker()

	id, org, m1, m2, m3 := setupCircle(cur, t)

	// Advance before everyone paid aborts.
	testing.SetRealm(testing.NewUserRealm(org))
	uassert.AbortsWithMessage(t, cur, "not all members have paid for this round", func() {
		AdvanceRound(cross(cur), id)
	})
	// Advance by a non-organizer aborts (even after all paid, checked below).
	depositAs(cur, m1, id, 1000)
	depositAs(cur, m2, id, 1000)
	testing.SetRealm(testing.NewUserRealm(m1))
	uassert.AbortsWithMessage(t, cur, "only the organizer can advance the round", func() {
		AdvanceRound(cross(cur), id)
	})
	depositAs(cur, m3, id, 1000)

	c := mustGetCircle(id)
	uassert.Equal(t, int64(3000), c.Pot)

	// Round 1: turn-taker is m1 (first to join).
	testing.SetRealm(testing.NewUserRealm(org))
	AdvanceRound(cross(cur), id)
	uassert.Equal(t, int64(3000), rb.GetCoin(m1, "ugnot"))
	uassert.Equal(t, int64(0), rb.GetCoin(m2, "ugnot"))
	uassert.Equal(t, int64(0), rb.GetCoin(m3, "ugnot"))
	c = mustGetCircle(id)
	uassert.Equal(t, 2, c.Round)
	uassert.Equal(t, int64(0), c.Pot)
	uassert.Equal(t, int64(3000), c.TotalPaidOut)
	uassert.Equal(t, 1, c.TurnsTaken[0])
	uassert.False(t, c.Paid[0])
	uassert.False(t, c.Paid[1])
	uassert.False(t, c.Paid[2])

	// Round 2: turn-taker is m2.
	depositAs(cur, m1, id, 1000)
	depositAs(cur, m2, id, 1000)
	depositAs(cur, m3, id, 1000)
	testing.SetRealm(testing.NewUserRealm(org))
	AdvanceRound(cross(cur), id)
	uassert.Equal(t, int64(3000), rb.GetCoin(m2, "ugnot"))
	uassert.Equal(t, int64(3000), rb.GetCoin(m1, "ugnot"))
	c = mustGetCircle(id)
	uassert.Equal(t, 3, c.Round)
	uassert.Equal(t, int64(6000), c.TotalPaidOut)
	uassert.Equal(t, 1, c.TurnsTaken[1])

	// Round 3: turn-taker is m3.
	depositAs(cur, m1, id, 1000)
	depositAs(cur, m2, id, 1000)
	depositAs(cur, m3, id, 1000)
	testing.SetRealm(testing.NewUserRealm(org))
	AdvanceRound(cross(cur), id)
	uassert.Equal(t, int64(3000), rb.GetCoin(m3, "ugnot"))
	c = mustGetCircle(id)
	uassert.Equal(t, 4, c.Round)
	uassert.Equal(t, int64(9000), c.TotalPaidOut)

	// Round 4 wraps around: turn-taker is m1 again.
	depositAs(cur, m1, id, 1000)
	depositAs(cur, m2, id, 1000)
	depositAs(cur, m3, id, 1000)
	testing.SetRealm(testing.NewUserRealm(org))
	AdvanceRound(cross(cur), id)
	uassert.Equal(t, int64(6000), rb.GetCoin(m1, "ugnot"))
	c = mustGetCircle(id)
	uassert.Equal(t, 2, c.TurnsTaken[0])
}

func TestTwoCirclesIndependent(cur realm, t *testing.T) {
	defer resetTestState()
	pkgAddr := chain.PackageAddress(testRealmPath)
	testing.IssueCoins(pkgAddr, chain.Coins{{Denom: "ugnot", Amount: 100000000}})
	org, m1, m2, m3 := testAddrs()

	testing.SetRealm(testing.NewUserRealm(org))
	id1 := CreateCircle(cross(cur), "Circle Satu", 1000, 4)
	id2 := CreateCircle(cross(cur), "Circle Dua", 500, 4)
	uassert.Equal(t, 2, CircleCount())

	testing.SetRealm(testing.NewUserRealm(m1))
	JoinCircle(cross(cur), id1)
	JoinCircle(cross(cur), id2)
	testing.SetRealm(testing.NewUserRealm(m2))
	JoinCircle(cross(cur), id1)
	JoinCircle(cross(cur), id2)
	testing.SetRealm(testing.NewUserRealm(org))
	StartCircle(cross(cur), id1)
	StartCircle(cross(cur), id2)

	// Deposit only in circle 1.
	depositAs(cur, m1, id1, 1000)
	depositAs(cur, m2, id1, 1000)
	c1 := mustGetCircle(id1)
	c2 := mustGetCircle(id2)
	uassert.Equal(t, int64(2000), c1.Pot)
	uassert.Equal(t, int64(0), c2.Pot)

	// Advance circle 1; circle 2 untouched.
	testing.SetRealm(testing.NewUserRealm(org))
	AdvanceRound(cross(cur), id1)
	c1 = mustGetCircle(id1)
	c2 = mustGetCircle(id2)
	uassert.Equal(t, 2, c1.Round)
	uassert.Equal(t, 1, c2.Round)
	uassert.Equal(t, int64(0), c2.Pot)
	_ = m3
}

func TestRender(cur realm, t *testing.T) {
	defer resetTestState()
	id, org, m1, _, _ := setupCircle(cur, t)
	_ = org
	out := Render("")
	uassert.True(t, len(out) > 0, "overview render must not be empty")
	detail := Render("/1")
	uassert.True(t, len(detail) > 0, "detail render must not be empty")
	// Member address appears in the detail view.
	uassert.True(t, containsStr(detail, m1.String()), "detail must list member 1")
	// Before any deposit, members show as BELUM BAYAR.
	uassert.True(t, containsStr(detail, "BELUM BAYAR"), "unpaid members must be flagged")
	// After m1 deposits, the flag flips for m1.
	depositAs(cur, m1, id, 1000)
	detail = Render("/1")
	uassert.True(t, containsStr(detail, "SUDAH BAYAR"), "paid member must show SUDAH BAYAR")
	uassert.True(t, containsStr(detail, "GILIRAN ROUND INI"), "turn-taker must be marked")
	// Unknown circle renders 404.
	uassert.Equal(t, "404: circle tidak ditemukan", Render("/99"))
}

func containsStr(haystack, needle string) bool {
	if len(needle) == 0 {
		return true
	}
	for i := 0; i+len(needle) <= len(haystack); i++ {
		if haystack[i:i+len(needle)] == needle {
			return true
		}
	}
	return false
}

package guardians

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
)

const maxMerkleProofDepth = 32

var (
	allowlistRoot       string
	allowlistRootLocked bool
)

func AllowlistRoot() string { return allowlistRoot }

func AllowlistRootLocked() bool { return allowlistRootLocked }

// SetAllowlistRoot accepts a lowercase/uppercase 32-byte SHA-256 hash in hex.
// The first sale unpause permanently locks the root for this deployment.
func SetAllowlistRoot(cur realm, root string) {
	assertAdmin(cur.Previous().Address())
	if !salePaused {
		panic("guardians: pause sale before setting allowlist root")
	}
	if allowlistRootLocked {
		panic("guardians: allowlist root is locked")
	}
	decoded, ok := decodeMerkleHash(root)
	if !ok || len(decoded) != sha256.Size {
		panic("guardians: invalid allowlist root")
	}
	allowlistRoot = hex.EncodeToString(decoded)
	chain.Emit("AllowlistRootConfigured", "root", allowlistRoot)
}

// AllowlistLeaf binds a claim to this chain, collection, phase, address,
// individual allowance and configured unit price.
func AllowlistLeaf(owner address, allowance int, unitPrice int64) string {
	payload := runtime.ChainID() + "|" +
		CollectionID() + "|" +
		salePhaseAllowlist + "|" +
		owner.String() + "|" +
		ufmt.Sprintf("%d", allowance) + "|" +
		ufmt.Sprintf("%d", unitPrice)
	return hashBytes([]byte(payload))
}

// VerifyAllowlist expects comma-separated 64-character hex sibling hashes.
// Pair hashing is sorted, so proofs do not need left/right direction flags.
func VerifyAllowlist(owner address, allowance int, unitPrice int64, proof string) bool {
	if allowlistRoot == "" || allowance < 1 || allowance > maxSupplyAsInt() {
		return false
	}

	computed := AllowlistLeaf(owner, allowance, unitPrice)
	siblings, ok := parseMerkleProof(proof)
	if !ok {
		return false
	}
	for _, sibling := range siblings {
		computed = hashMerklePair(computed, sibling)
	}
	return computed == allowlistRoot
}

func MintAllowlist(cur realm, quantity, allowance int, unitPrice int64, proof string) {
	if !cur.Previous().IsUserCall() {
		panic("guardians: only direct user calls can mint")
	}
	if !allowlistSaleOpenAt(time.Now().Unix()) {
		panic("guardians: allowlist sale is not active")
	}
	if unitPrice != saleConfig.allowlistPrice {
		panic("guardians: allowlist price mismatch")
	}
	if allowance < 1 || allowance > saleConfig.allowlistLimit {
		panic("guardians: invalid allowlist allowance")
	}

	caller := cur.Previous().Address()
	if !VerifyAllowlist(caller, allowance, unitPrice, proof) {
		panic("guardians: invalid allowlist proof")
	}
	assertSaleMint(quantity, AllowlistMinted(caller), allowance)
	required := requiredPayment(unitPrice, quantity)
	sent := unsafe.OriginSend()
	assertExactPayment(sent, required)

	mintAllocatedTokens(caller, quantity, 0)
	allowlistMintedByWallet.Set(caller.String(), AllowlistMinted(caller)+quantity)
	forwardPayment(cur, sent)

	chain.Emit(
		"AllowlistMint",
		"minter", caller.String(),
		"quantity", ufmt.Sprintf("%d", quantity),
		"allowance", ufmt.Sprintf("%d", allowance),
		"paid", ufmt.Sprintf("%d", required),
	)
}

func parseMerkleProof(proof string) ([]string, bool) {
	if proof == "" {
		return []string{}, true
	}
	parts := strings.Split(proof, ",")
	if len(parts) > maxMerkleProofDepth {
		return nil, false
	}
	for i, part := range parts {
		decoded, ok := decodeMerkleHash(part)
		if !ok {
			return nil, false
		}
		parts[i] = hex.EncodeToString(decoded)
	}
	return parts, true
}

func hashMerklePair(first, second string) string {
	left, leftOK := decodeMerkleHash(first)
	right, rightOK := decodeMerkleHash(second)
	if !leftOK || !rightOK {
		return ""
	}
	if second < first {
		left, right = right, left
	}
	combined := make([]byte, 0, sha256.Size*2)
	combined = append(combined, left...)
	combined = append(combined, right...)
	return hashBytes(combined)
}

func hashBytes(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func decodeMerkleHash(value string) ([]byte, bool) {
	if len(value) != sha256.Size*2 {
		return nil, false
	}
	decoded, err := hex.DecodeString(value)
	if err != nil || len(decoded) != sha256.Size {
		return nil, false
	}
	return decoded, true
}

func maxSupplyAsInt() int { return int(maxSupply) }

